#ifndef HCCL_ALGO_DIMS_H
#define HCCL_ALGO_DIMS_H

#include <stdint.h>
#include "hccl/hccl_types.h"

/* ===== Engine 维度（5 种）===== */
typedef enum {
    HCCL_ENGINE_AICPU = 0,
    HCCL_ENGINE_CCU_MS,
    HCCL_ENGINE_CCU_SCHED,
    HCCL_ENGINE_AIV,
    HCCL_ENGINE_DPU,
    HCCL_ENGINE_COUNT
} hcclEngineType_t;

/* ===== Executor 维度（5 种）===== */
typedef enum {
    HCCL_EXEC_SEQUENCE = 0,
    HCCL_EXEC_SOLE,
    HCCL_EXEC_PARALLEL,
    HCCL_EXEC_PIPILINE,
    HCCL_EXEC_CONCUR,
    HCCL_EXEC_COUNT
} hcclExecutorType_t;

/* ===== Template 维度（6 种）===== */
typedef enum {
    HCCL_TPL_MESH = 0,
    HCCL_TPL_NHR,
    HCCL_TPL_MESH_TWO_SHOT,
    HCCL_TPL_MESH_ONE_SHOT,
    HCCL_TPL_MESH_CHUNK,
    HCCL_TPL_MESH_2DIE,
    HCCL_TPL_COUNT
} hcclTemplateType_t;

/* ===== OpType 查找函数（基于 HcclCMDType，定义于 hccl_types.h）===== */

static inline const char* HcclOpTypeToPascal(HcclCMDType opType)
{
    switch (opType) {
        case HCCL_CMD_ALLREDUCE:
            return "AllReduce";
        case HCCL_CMD_ALLGATHER:
            return "AllGather";
        case HCCL_CMD_BROADCAST:
            return "Broadcast";
        case HCCL_CMD_REDUCE:
            return "Reduce";
        case HCCL_CMD_REDUCE_SCATTER:
            return "ReduceScatter";
        case HCCL_CMD_SCATTER:
            return "Scatter";
        case HCCL_CMD_ALLTOALL:
            return "AlltoAll";
        case HCCL_CMD_ALLTOALLV:
            return "AlltoAllV";
        default:
            return nullptr;
    }
}

#endif /* HCCL_ALGO_DIMS_H */

