89	                static_cast<int>(allAlgos.algElements[i].opType), algName);
90	            continue;
91	        }
92	
93	        AlgoDims dims = {};
94	        if (Lookup2D(algName, opTypePascal, dims)) {
95	            cache_[algName] = dims;
