97	            HCCL_WARNING("[AlgoNameMapper] lookup failed, algName=%s.", algName);
98	        }
99	    }
100	    HCCL_DEBUG("[AlgoNameMapper] init done, cached %zu algorithms.", cache_.size());
101	}
