54	// 小写字符串转换（自由函数，供全局使用）
55	static std::string ToLowerStr(const std::string& s)
56	{
57	    std::string r = s;
58	    std::transform(r.begin(), r.end(), r.begin(), [](unsigned char c) {
59	        return std::tolower(c);
60	    });
61	    return r;
62	}
63	
64	// ===========================================================================
65	// 用户算法配置解析器（内部实现类）
66	// ===========================================================================
67	std::string UnderscoreToCamelCase(const std::string& name)
68	{
69	    std::string result;
70	    bool nextUpper = false;
71	    for (char c : name) {
72	        if (c == '_') {
73	            nextUpper = true;
74	        } else {
75	            if (nextUpper) {
76	                result += static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
77	                nextUpper = false;
78	            } else {
79	                result += c;
80	            }
81	        }
82	    }
83	    return result;
84	}
85	
86	// ===========================================================================
87	// 用户算法配置解析器（内部实现类）
88	// ===========================================================================
89	class AlgoParserImpl {
90	public:
91	    explicit AlgoParserImpl(const std::string& input) : input_(input), pos_(0) {}
92	
93	    HcclResult Parse(std::vector<HcclAlgoExecutor>& result)
94	    {
95	        SkipWs();
96	        while (!AtEnd()) {
97	            HcclAlgoExecutor exec;
98	            CHK_RET(ParseSegment(exec));
99	            CompactAlgoList(exec.algoList);
100	            result.push_back(std::move(exec));
101	            SkipWs();
102	            if (Eat(';')) {
103	                SkipWs();
104	                continue;
105	            }
106	            break;
107	        }
108	        SkipWs();
109	        if (!AtEnd()) {
110	            HCCL_ERROR(
111	                "[HcclAlgoParser] parse algo config failed, standard format: \"opType:executorType{level0=algoType, "
112	                "level1=algoType, level2=algoType};...\", "
113	                "trailing chars at pos %zu: [%s]",
114	                pos_, input_.substr(pos_).c_str());
115	            return HCCL_E_PARA;
116	        }
117	        return HCCL_SUCCESS;
118	    }
119	
120	private:
121	    const std::string& input_;
122	    size_t pos_;
123	
124	    // 哨兵值：标记 level 未显式指定
125	    static constexpr uint32_t LEVEL_UNSPECIFIED = UINT32_MAX;
126	
127	    // ---- 辅助函数 ----
128	
129	    // 有序插入：将 algo 按 level 插入到 algoList 的正确位置
130	    // level 由 algoList 的 index 隐式表达，插入后保持 index 与 level 对应
131	    void InsertAlgoOrdered(std::vector<HcclAlgo>& algoList, HcclAlgo algo, uint32_t level) const
132	    {
133	        if (level == LEVEL_UNSPECIFIED) {
134	            // 未指定 level，追加到末尾
135	            algoList.push_back(std::move(algo));
136	            return;
137	        }
138	        // 扩展到足够大小（中间空位用默认 HcclAlgo 填充，后续会被覆盖或保留）
139	        if (level >= algoList.size()) {
140	            algoList.resize(level + 1);
141	        }
142	        algoList[level] = std::move(algo);
143	    }
144	
145	    // 补全 algoList：消除空位，确保 index 连续且按 level 升序
146	    // 空位是指 algoType 为空的默认 HcclAlgo 条目，由 resize 产生
147	    void CompactAlgoList(std::vector<HcclAlgo>& algoList) const
148	    {
149	        // 先将所有有效条目（algoType 非空）按 index(=level) 收集
150	        std::vector<std::pair<uint32_t, HcclAlgo>> validItems;
151	        for (uint32_t i = 0; i < static_cast<uint32_t>(algoList.size()); i++) {
152	            if (!algoList[i].algoType.empty()) {
153	                validItems.emplace_back(i, std::move(algoList[i]));
154	            }
155	        }
156	        // 已按 index 升序（遍历顺序），直接紧凑写入
157	        algoList.clear();
158	        for (auto& p : validItems) {
159	            algoList.push_back(std::move(p.second));
160	        }
161	    }
162	
163	    // ---- 基础词法 ----
164	    char Peek() const { return pos_ < input_.size() ? input_[pos_] : '\0'; }
165	    char Peek2() const { return pos_ + 1 < input_.size() ? input_[pos_ + 1] : '\0'; }
166	    // 尝试消费字符 c：当前字符匹配则前进一步返回 true，否则返回 false
167	    bool Eat(char c)
168	    {
169	        if (Peek() == c) {
170	            pos_++;
171	            return true;
172	        }
173	        return false;
174	    }
175	    bool AtEnd() const { return pos_ >= input_.size(); }
176	
177	    void SkipWs()
178	    {
179	        while (pos_ < input_.size() && std::isspace(static_cast<unsigned char>(input_[pos_]))) {
180	            pos_++;
181	        }
182	    }
183	
184	    // 解析标识符：字母/数字/下划线/连字符（规则8）
185	    bool ParseIdentifier(std::string& name)
186	    {
187	        SkipWs();
188	        size_t start = pos_;
189	        while (pos_ < input_.size()) {
190	            char c = input_[pos_];
191	            if (std::isalnum(static_cast<unsigned char>(c)) || c == '_' || c == '-') {
192	                pos_++;
193	            } else {
194	                break;
195	            }
196	        }
197	        if (pos_ == start)
198	            return false;
199	        name = input_.substr(start, pos_ - start);
200	        return true;
201	    }
202	
203	    // ---- 文法规则 ----
204	
205	    // segment := [opType ':'] executor_expr
206	    HcclResult ParseSegment(HcclAlgoExecutor& exec)
207	    {
208	        size_t savePos = pos_;
209	        std::string name;
210	        if (ParseIdentifier(name)) {
211	            SkipWs();
212	            if (Peek() == ':' && Peek2() != ':') {
213	                Eat(':');
214	                std::string opType = ToLowerStr(name);
215	                if (OP_TYPES.find(opType) == OP_TYPES.end()) {
216	                    HCCL_ERROR("[HcclAlgoParser] invalid opType [%s] at pos %zu", opType.c_str(), pos_);
217	                    return HCCL_E_PARA;
218	                }
219	                exec.opType = opType;
220	                SkipWs();
221	            } else {
222	                pos_ = savePos;
223	            }
224	        }
225	        return ParseExecutorExpr(exec);
226	    }
227	
228	    // executor_expr := 'not' '(' inner ')' | executor_unit | template_name(shorthand)
229	    HcclResult ParseExecutorExpr(HcclAlgoExecutor& exec)
230	    {
231	        SkipWs();
232	        size_t savePos = pos_;
233	        std::string name;
234	        if (ParseIdentifier(name)) {
235	            SkipWs();
236	            if (ToLowerStr(name) == "not" && Peek() == '(') {
237	                Eat('(');
238	                SkipWs();
239	                CHK_RET(ParseExecutorUnitOrAtom(exec));
240	                SkipWs();
241	                if (!Eat(')')) {
242	                    HCCL_ERROR("[HcclAlgoParser] expected ')' after not(...) at pos %zu", pos_);
243	                    return HCCL_E_PARA;
244	                }
245	                exec.enable = false;
246	                return HCCL_SUCCESS;
247	            }
248	            pos_ = savePos;
249	        }
250	        return ParseExecutorUnitOrAtom(exec);
251	    }
252	
253	    // executor_unit | template_name(shorthand)
254	    HcclResult ParseExecutorUnitOrAtom(HcclAlgoExecutor& exec)
255	    {
256	        SkipWs();
257	        std::string name;
258	        if (!ParseIdentifier(name)) {
259	            HCCL_ERROR("[HcclAlgoParser] expected executor or template at pos %zu", pos_);
260	            return HCCL_E_PARA;
261	        }
262	        SkipWs();
263	        if (Peek() == '{') {
264	            std::string executorType = ToLowerStr(name);
265	            if (EXECUTOR_TYPES.find(executorType) == EXECUTOR_TYPES.end()) {
266	                HCCL_ERROR("[HcclAlgoParser] invalid executorType [%s] at pos %zu", executorType.c_str(), pos_);
267	                return HCCL_E_PARA;
268	            }
269	            exec.executorType = executorType;
270	            Eat('{');
271	            CHK_RET(ParseTemplateList(exec.algoList));
272	            SkipWs();
273	            if (!Eat('}')) {
274	                HCCL_ERROR("[HcclAlgoParser] expected '}' at pos %zu", pos_);
275	                return HCCL_E_PARA;
276	            }
277	            return HCCL_SUCCESS;
278	        }
279	        // template shorthand: name => sole{name}
280	        std::string algoType = ToLowerStr(UnderscoreToCamelCase(name));
281	        if (ALGO_TYPES.find(algoType) == ALGO_TYPES.end()) {
282	            HCCL_ERROR("[HcclAlgoParser] invalid algoType [%s] at pos %zu", algoType.c_str(), pos_);
283	            return HCCL_E_PARA;
284	        }
285	        exec.executorType = "sole";
286	        HcclAlgo algo;
287	        algo.algoType = algoType;
288	        algo.enable = true;
289	        InsertAlgoOrdered(exec.algoList, std::move(algo), LEVEL_UNSPECIFIED);
290	        return HCCL_SUCCESS;
291	    }
292	
293	    // tpl_list := tpl_item (',' tpl_item)*
294	    HcclResult ParseTemplateList(std::vector<HcclAlgo>& algoList)
295	    {
296	        SkipWs();
297	        if (Peek() == '}')
298	            return HCCL_SUCCESS;
299	        while (true) {
300	            HcclAlgo algo;
301	            uint32_t level = LEVEL_UNSPECIFIED;
302	            CHK_RET(ParseTemplateItem(algo, level));
303	            InsertAlgoOrdered(algoList, std::move(algo), level);
304	            SkipWs();
305	            if (!Eat(','))
306	                break;
307	            SkipWs();
308	        }
309	        return HCCL_SUCCESS;
310	    }
311	
312	    // tpl_item := ['level' digit '=' ] tpl_expr
313	    HcclResult ParseTemplateItem(HcclAlgo& algo, uint32_t& level)
314	    {
315	        SkipWs();
316	        size_t savePos = pos_;
317	        std::string name;
318	        if (ParseIdentifier(name)) {
319	            // 判定 "levelN"
320	            if (name.size() > 5 && ToLowerStr(name.substr(0, 5)) == "level") {
321	                bool allDigit = true;
322	                for (size_t i = 5; i < name.size(); i++) {
323	                    if (!std::isdigit(static_cast<unsigned char>(name[i]))) {
324	                        allDigit = false;
325	                        break;
326	                    }
327	                }
328	                if (allDigit) {
329	                    SkipWs();
330	                    if (Eat('=')) {
331	                        try {
332	                            unsigned long parsed = std::stoul(name.substr(5));
333	                            if (parsed > UINT32_MAX) {
334	                                HCCL_ERROR("[HcclAlgoParser] level %lu exceeds uint32_t range", parsed);
335	                                return HCCL_E_PARA;
336	                            }
337	                            level = static_cast<uint32_t>(parsed);
338	                        } catch (...) {
339	                            HCCL_ERROR("[HcclAlgoParser] invalid level: %s", name.c_str());
340	                            return HCCL_E_PARA;
341	                        }
342	                        SkipWs();
343	                        return ParseTemplateExpr(algo);
344	                    }
345	                }
346	            }
347	            pos_ = savePos;
348	        }
349	        return ParseTemplateExpr(algo);
350	    }
351	
352	    // tpl_expr := 'not' '(' template_name ')' | template_name
353	    HcclResult ParseTemplateExpr(HcclAlgo& algo)
354	    {
355	        SkipWs();
356	        size_t savePos = pos_;
357	        std::string name;
358	        if (ParseIdentifier(name)) {
359	            SkipWs();
360	            if (ToLowerStr(name) == "not" && Peek() == '(') {
361	                Eat('(');
362	                SkipWs();
363	                CHK_RET(ParseTemplateAtom(algo));
364	                algo.enable = false;
365	                SkipWs();
366	                if (!Eat(')')) {
367	                    HCCL_ERROR("[HcclAlgoParser] expected ')' after not(template) at pos %zu", pos_);
368	                    return HCCL_E_PARA;
369	                }
370	                return HCCL_SUCCESS;
371	            }
372	            pos_ = savePos;
373	        }
374	        return ParseTemplateAtom(algo);
375	    }
376	
377	    // template_name
378	    HcclResult ParseTemplateAtom(HcclAlgo& algo)
379	    {
380	        SkipWs();
381	        std::string name;
382	        if (!ParseIdentifier(name)) {
383	            HCCL_ERROR("[HcclAlgoParser] expected template name at pos %zu", pos_);
384	            return HCCL_E_PARA;
385	        }
386	        std::string algoType = ToLowerStr(UnderscoreToCamelCase(name));
387	        if (ALGO_TYPES.find(algoType) == ALGO_TYPES.end()) {
388	            HCCL_ERROR("[HcclAlgoParser] invalid algoType [%s] at pos %zu", algoType.c_str(), pos_);
389	            return HCCL_E_PARA;
390	        }
391	        algo.algoType = algoType;
392	        return HCCL_SUCCESS;
393	    }
394	};
