446	// ===========================================================================
447	// CostModel 刷新：UpdateCostModelWithAlgo
448	// ===========================================================================
449	// 拼接算法名：[EngineType][OpType(cap)][ExecutorType(cap)][AlgoType0(cap)][AlgoType1(cap)]...
450	// 驼峰命名：首字段（EngineType）小写开头，后续字段首字母大写
451	static std::string ComposeAlgoName(
452	    const std::string& engineType, const std::string& opType, const std::string& executorType,
453	    const std::vector<HcclAlgo>& algoList)
454	{
455	    std::string name = engineType; // 首字段保持小写（camelCase）
456	    name += OP_TYPES.at(opType);
457	    name += EXECUTOR_TYPES.at(executorType);
458	    for (const auto& algo : algoList) {
459	        name += ALGO_TYPES.at(algo.algoType);
460	    }
461	    return name;
462	}
463	
464	// 拼接算法名前缀（algoList 为空时使用）：[EngineType][OpType(cap)][ExecutorType(cap)]
465	static std::string
466	ComposeAlgoPrefix(const std::string& engineType, const std::string& opType, const std::string& executorType)
467	{
468	    return engineType + OP_TYPES.at(opType) + EXECUTOR_TYPES.at(executorType);
469	}
470	
471	// 前缀匹配
472	static bool StartsWith(const std::string& str, const std::string& prefix)
473	{
474	    return str.size() >= prefix.size() && str.compare(0, prefix.size(), prefix) == 0;
475	}
476	
477	// algoType 驼峰名列表（按长度降序，避免 "Mesh" 误匹配 "Mesh2Die"）
478	static const std::vector<std::string> SORTED_ALGO_NAMES = []() {
479	    std::vector<std::string> names;
480	    for (const auto& pair : ALGO_TYPES) {
481	        names.push_back(pair.second);
482	    }
483	    std::sort(names.begin(), names.end(), [](const std::string& a, const std::string& b) {
484	        return a.size() > b.size();
485	    });
486	    return names;
487	}();
488	
489	// 逐个算法名检查是否匹配 algoList 模式（规则 4.6.2，支持多个 level 同时有 not）
490	// 前缀 engine+opType+executorType 精确匹配，后续 algoType 段逐个匹配：
491	//   enable=true  → 该位置必须是指定 algoType
492	//   enable=false → 该位置可以是任意 algoType，但不能是指定 algoType
493	static bool MatchesAlgoPattern(
494	    const std::string& key, const std::string& engine, const std::string& opType, const std::string& executorType,
495	    const std::vector<HcclAlgo>& algoList)
496	{
497	    std::string prefix = engine + OP_TYPES.at(opType) + EXECUTOR_TYPES.at(executorType);
498	    if (!StartsWith(key, prefix))
499	        return false;
500	    std::string remaining = key.substr(prefix.size());
501	    size_t pos = 0;
502	    for (const auto& algo : algoList) {
503	        // 尝试在当前位置匹配一个 algoType（长名优先）
504	        std::string matched;
505	        for (const auto& name : SORTED_ALGO_NAMES) {
506	            if (remaining.compare(pos, name.size(), name) == 0) {
507	                matched = name;
508	                break;
509	            }
510	        }
511	        if (matched.empty())
512	            return false;
513	        if (algo.enable) {
514	            if (matched != ALGO_TYPES.at(algo.algoType))
515	                return false;
516	        } else {
517	            if (matched == ALGO_TYPES.at(algo.algoType))
518	                return false;
519	        }
520	        pos += matched.size();
521	    }
522	    return pos == remaining.size();
523	}
524	
525	// 判断算法名是否属于指定 OpType
526	// costModel 算法名使用 ENGINE_TYPES.second（驼峰）+ OP_TYPES.second + EXECUTOR_TYPES.second 格式
527	static bool IsAlgoOfOpType(const std::string& algoKey, const std::string& opType)
528	{
529	    std::string camelOpType = OP_TYPES.at(opType);
530	    for (const auto& enginePair : ENGINE_TYPES) {
531	        std::string prefix = enginePair.second + camelOpType;
532	        if (!StartsWith(algoKey, prefix) || algoKey.size() == prefix.size()) {
533	            continue;
534	        }
535	        std::string rest = algoKey.substr(prefix.size());
536	        for (const auto& execPair : EXECUTOR_TYPES) {
537	            if (StartsWith(rest, execPair.second)) {
538	                return true;
539	            }
540	        }
541	    }
542	    return false;
543	}
544	
545	// 判断算法名是否包含 send 或 recv（大小写不敏感）
546	// 规则 4.6：send/recv 算法名不参与 count=0 的排除逻辑
547	static bool ContainsSendRecv(const std::string& algoKey)
548	{
549	    std::string lower = ToLowerStr(algoKey);
550	    return lower.find("send") != std::string::npos || lower.find("recv") != std::string::npos;
551	}
552	
553	// 匹配过程共享上下文，用于减少函数参数个数
554	struct AlgoMatchCtx {
555	    CostModel& model;
556	    const std::vector<std::string>& engineTypes;
557	    const HcclAlgoExecutor& exec;
558	    const std::map<std::string, int>& keyToIdx;
559	    std::set<std::string>& matchedOpTypes;
560	};
561	
562	// 单次 opType 匹配的结果
563	struct MatchResult {
564	    std::vector<std::string> matchedNames;
565	    bool negatedFound = false;
566	};
567	
568	// 对单个 opType 遍历所有 engine 收集匹配结果（三种匹配模式）
569	static void CollectMatchedNamesForOpType(
570	    AlgoMatchCtx& ctx, const std::string& opType, bool isExecNegated, bool hasNegatedAlgo, MatchResult& result)
571	{
572	    for (const auto& engine : ctx.engineTypes) {
573	        if (hasNegatedAlgo) {
574	            for (int i = 0; i < ctx.model.count; i++) {
575	                if (ctx.model.costAlgoParams[i].count == 0)
576	                    continue;
577	                std::string key(ctx.model.costAlgoParams[i].algName ? ctx.model.costAlgoParams[i].algName : "");
578	                if (MatchesAlgoPattern(key, engine, opType, ctx.exec.executorType, ctx.exec.algoList)) {
579	                    result.matchedNames.push_back(key);
580	                }
581	            }
582	        } else if (ctx.exec.algoList.empty()) {
583	            std::string prefix = ComposeAlgoPrefix(engine, opType, ctx.exec.executorType);
584	            for (int i = 0; i < ctx.model.count; i++) {
585	                std::string key(ctx.model.costAlgoParams[i].algName ? ctx.model.costAlgoParams[i].algName : "");
586	                if (!StartsWith(key, prefix))
587	                    continue;
588	                if (isExecNegated) {
589	                    ctx.model.costAlgoParams[i].count = 0;
590	                    result.negatedFound = true;
591	                } else if (ctx.model.costAlgoParams[i].count != 0) {
592	                    result.matchedNames.push_back(key);
593	                }
594	            }
595	        } else {
596	            std::string fullName = ComposeAlgoName(engine, opType, ctx.exec.executorType, ctx.exec.algoList);
597	            auto it = ctx.keyToIdx.find(fullName);
598	            if (it == ctx.keyToIdx.end())
599	                continue;
600	            int algoIdx = it->second;
601	            if (isExecNegated) {
602	                ctx.model.costAlgoParams[algoIdx].count = 0;
603	                result.negatedFound = true;
604	            } else if (ctx.model.costAlgoParams[algoIdx].count != 0) {
605	                result.matchedNames.push_back(fullName);
606	            }
607	        }
608	    }
609	}
610	
611	// 匹配后处理：标记 OpType 并排除未匹配算法
612	static void
613	ProcessMatchedResults(AlgoMatchCtx& ctx, const std::string& opType, bool isExecNegated, const MatchResult& result)
614	{
615	    if (!isExecNegated && !result.matchedNames.empty()) {
616	        ctx.matchedOpTypes.insert(opType);
617	        for (int i = 0; i < ctx.model.count; i++) {
618	            std::string key(ctx.model.costAlgoParams[i].algName ? ctx.model.costAlgoParams[i].algName : "");
619	            if (!IsAlgoOfOpType(key, opType))
620	                continue;
621	            bool isMatched = false;
622	            for (const auto& name : result.matchedNames) {
623	                if (key == name) {
624	                    isMatched = true;
625	                    break;
626	                }
627	            }
628	            if (!isMatched && !ContainsSendRecv(key)) {
629	                ctx.model.costAlgoParams[i].count = 0;
630	            }
631	        }
632	    } else if (isExecNegated && result.negatedFound) {
633	        ctx.matchedOpTypes.insert(opType);
634	    }
635	}
636	
637	// 排除不在engineTypes列表中的算法
638	static HcclResult ExcludeAlgosNotInEngines(CostModel& model, const std::vector<std::string>& engineTypes)
639	{
640	    if (engineTypes.empty()) {
641	        HCCL_ERROR("engineTypes is empty");
642	        return HCCL_E_PARA;
643	    }
644	
645	    std::string engines;
646	    for (const auto& engine : engineTypes) {
647	        if (!engines.empty())
648	            engines += ", ";
649	        engines += engine;
650	    }
651	    HCCL_INFO("[UpdateCostModelWithAlgo] engineTypes: [%s]", engines.c_str());
652	
653	    for (int i = 0; i < model.count; i++) {
654	        if (model.costAlgoParams[i].count == 0)
655	            continue;
656	        std::string key(model.costAlgoParams[i].algName ? model.costAlgoParams[i].algName : "");
657	        if (ContainsSendRecv(key))
658	            continue; // send/recv 不处理
659	        bool inEngine = false;
660	        for (const auto& engine : engineTypes) {
661	            if (StartsWith(key, engine)) {
662	                inEngine = true;
663	                break;
664	            }
665	        }
666	        if (!inEngine) {
667	            model.costAlgoParams[i].count = 0;
668	        }
669	    }
670	    return HCCL_SUCCESS;
671	}
672	
673	// 主函数
674	HcclResult
675	UpdateCostModelWithAlgo(const HcclAlgoParser& algoParser, CostModel& model, const std::vector<std::string>& engineTypes)
676	{
677	    CHK_RET(ExcludeAlgosNotInEngines(model, engineTypes));
678	
679	    std::map<std::string, int> keyToIdx;
680	    for (int i = 0; i < model.count; i++) {
681	        if (model.costAlgoParams[i].algName != nullptr) {
682	            keyToIdx[model.costAlgoParams[i].algName] = i;
683	        }
684	    }
685	    std::set<std::string> matchedOpTypes;
686	
687	    for (int idx = static_cast<int>(algoParser.executorList.size()) - 1; idx >= 0; idx--) {
688	        const auto& exec = algoParser.executorList[idx];
689	        if (exec.executorType.empty())
690	            continue;
691	        if (EXECUTOR_TYPES.find(exec.executorType) == EXECUTOR_TYPES.end())
692	            continue;
693	        bool algoValid = true;
694	        for (const auto& algo : exec.algoList) {
695	            if (ALGO_TYPES.find(algo.algoType) == ALGO_TYPES.end()) {
696	                algoValid = false;
697	                break;
698	            }
699	        }
700	        if (!algoValid)
701	            continue;
702	
703	        std::vector<std::string> unprocessedOps;
704	        if (exec.opType.empty()) {
705	            for (const auto& pair : OP_TYPES) {
706	                if (matchedOpTypes.find(pair.first) == matchedOpTypes.end())
707	                    unprocessedOps.push_back(pair.first);
708	            }
709	        } else if (
710	            OP_TYPES.find(exec.opType) != OP_TYPES.end() && matchedOpTypes.find(exec.opType) == matchedOpTypes.end()) {
711	            unprocessedOps.push_back(exec.opType);
712	        }
713	        if (unprocessedOps.empty())
714	            continue;
715	
716	        bool isExecNegated = !exec.enable;
717	        bool hasNegatedAlgo
718	            = !isExecNegated && std::any_of(exec.algoList.begin(), exec.algoList.end(), [](const HcclAlgo& a) {
719	                  return !a.enable;
720	              });
721	
722	        AlgoMatchCtx ctx{model, engineTypes, exec, keyToIdx, matchedOpTypes};
723	        for (const auto& opType : unprocessedOps) {
724	            MatchResult result;
725	            CollectMatchedNamesForOpType(ctx, opType, isExecNegated, hasNegatedAlgo, result);
726	            ProcessMatchedResults(ctx, opType, isExecNegated, result);
727	            bool allMatched = true;
728	            for (const auto& pair : OP_TYPES) {
729	                if (matchedOpTypes.find(pair.first) == matchedOpTypes.end()) {
730	                    allMatched = false;
731	                    break;
732	                }
733	            }
734	            if (allMatched) {
735	                return HCCL_SUCCESS;
736	            }
737	        }
738	    }
739	    return HCCL_SUCCESS;
740	}
741	
742	HcclResult FilterCmByHcclAlgo(HcclComm comm, CostModel& cm, const std::vector<std::string>& candidateEngineNames)
743	{
744	    // 获取配置：通信域 hcclAlgo 优先，其次环境变量 HCCL_ALGO
745	    std::string algoConfig;
746	    HcclResult ret = HcclGetHcclAlgo(comm, algoConfig);
747	    if (ret != HCCL_SUCCESS) {
748	        HCCL_WARNING("[FilterCmByHcclAlgo] HcclGetHcclAlgo failed, ret[%d], try env variable.", ret);
749	        algoConfig.clear();
750	    }
751	
752	    if (algoConfig.empty()) {
753	        algoConfig = GetEnv("HCCL_ALGO");
754	        if (algoConfig == "EmptyString") {
755	            HCCL_WARNING("[FilterCmByHcclAlgo] both hcclAlgo and HCCL_ALGO env are empty, skip filtering.");
756	            return HCCL_SUCCESS;
757	        }
758	    }
759	    HCCL_INFO("[FilterCmByHcclAlgo] use algo config: [%s]", algoConfig.c_str());
760	
761	    // 解析算法配置
762	    HcclAlgoParser algoParser;
763	    ret = algoParser.Parser(algoConfig);
764	    if (ret != HCCL_SUCCESS) {
765	        HcclDevType deviceType;
766	        CHK_RET(HcclGetDeviceType(deviceType));
767	        if (deviceType != HcclDevType::DEV_TYPE_910_93) {
768	            ret = SetHcclAlgoConfig(algoConfig);
769	            HCCL_WARNING("[FilterCmByHcclAlgo] parse algo failed, try Parse with old rules: ret[%d] .", ret);
770	        }
771	        return ret;
772	    }
773	
774	    // 刷新 CostModel,使用 selector 传入的候选引擎前缀
775	    ret = UpdateCostModelWithAlgo(algoParser, cm, candidateEngineNames);
776	    if (ret != HCCL_SUCCESS) {
777	        HCCL_ERROR("[FilterCmByHcclAlgo] UpdateCostModelWithAlgo failed, ret[%d].", ret);
778	        return ret;
779	    }
780	
781	    std::string content;
782	    for (int i = 0; i < cm.count; i++) {
783	        if (!content.empty()) {
784	            content += ", ";
785	        }
786	        content += "[" + std::to_string(i) + "]"
787	                   + std::string(cm.costAlgoParams[i].algName ? cm.costAlgoParams[i].algName : "null") + ":"
788	                   + std::to_string(cm.costAlgoParams[i].count);
789	    }
790	    HCCL_DEBUG("[FilterCmByHcclAlgo] final costModel: %s", content.c_str());
791	
792	    HCCL_INFO("[FilterCmByHcclAlgo] filter costModel success.");
793	    return HCCL_SUCCESS;
794	}
795	
796	// ---------------------------------------------------------------------------
797	// 派生数组接口：从 map 构建 AlgoDimEntry 数组，供 selector 遍历
798	// ---------------------------------------------------------------------------
799	static std::vector<AlgoDimEntry> BuildDimEntries(const std::map<std::string, std::string>& m)
800	{
801	    std::vector<AlgoDimEntry> v;
802	    v.reserve(m.size());
803	    for (const auto& p : m) {
804	        v.push_back({p.first.c_str(), p.second.c_str()});
805	    }
806	    return v;
807	}
808	
809	const AlgoDimEntry* GetAlgoEngines(int& count)
810	{
811	    static auto entries = BuildDimEntries(ENGINE_TYPES);
812	    count = static_cast<int>(entries.size());
813	    return entries.data();
814	}
815	
816	const AlgoDimEntry* GetAlgoExecutors(int& count)
817	{
818	    static auto entries = BuildDimEntries(EXECUTOR_TYPES);
819	    count = static_cast<int>(entries.size());
820	    return entries.data();
821	}
822	
823	const AlgoDimEntry* GetAlgoTemplates(int& count)
824	{
825	    static auto entries = BuildDimEntries(ALGO_TYPES);
826	    count = static_cast<int>(entries.size());
827	    return entries.data();
828	}
